<?php require __DIR__.'/../app/bootstrap.php';
if(isset($_GET['logout'])){session_destroy();header('Location: admin.php');exit;}
if(empty($_SESSION['user'])){if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=$pdo->prepare("SELECT * FROM users WHERE username=?");$s->execute([$_POST['username']]);$u=$s->fetch();if($u&&password_verify($_POST['password'],$u['password'])){$_SESSION['user']=$u;header('Location: admin.php');exit;}$error='Login gagal';} ?><!doctype html><html lang="id"><body style="font-family:Arial;background:#f4f7fb"><form method="post" style="max-width:400px;margin:100px auto;background:#fff;padding:30px;border-radius:15px"><h2>Admin Repository</h2><?=isset($error)?'<p>'.e($error).'</p>':''?><input type="hidden" name="csrf" value="<?=csrf()?>"><input name="username" placeholder="Username" required style="width:100%;padding:12px;margin:7px 0"><input type="password" name="password" placeholder="Password" required style="width:100%;padding:12px;margin:7px 0"><button style="width:100%;padding:12px">Masuk</button></form></body></html><?php exit;}
if(isset($_POST['save'])){check_csrf();$file=null;if(!empty($_FILES['pdf']['name'])){$ext=strtolower(pathinfo($_FILES['pdf']['name'],PATHINFO_EXTENSION));if($ext!=='pdf')exit('Hanya PDF');if(!is_dir(__DIR__.'/uploads'))mkdir(__DIR__.'/uploads',0755,true);$name=bin2hex(random_bytes(12)).'.pdf';if(!move_uploaded_file($_FILES['pdf']['tmp_name'],__DIR__.'/uploads/'.$name))exit('Upload file gagal');$file='uploads/'.$name;}
$s=$pdo->prepare("INSERT INTO documents(title,author,nim,study_program_id,type_id,year,abstract,keywords,file_path,status,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?)");$s->execute([$_POST['title'],$_POST['author'],$_POST['nim'],$_POST['study_program_id']?:null,$_POST['type_id']?:null,$_POST['year'],$_POST['abstract'],$_POST['keywords'],$file,$_POST['status'],$_SESSION['user']['id']]);log_action($pdo,'create_document',$_POST['title']);header('Location: admin.php');exit;}
if(isset($_GET['publish'])){$id=(int)$_GET['publish'];$pdo->prepare("UPDATE documents SET status='published' WHERE id=?")->execute([$id]);log_action($pdo,'publish_document',(string)$id);header('Location: admin.php');exit;}
$docs=$pdo->query("SELECT d.*,sp.name program,dt.name type FROM documents d LEFT JOIN study_programs sp ON sp.id=d.study_program_id LEFT JOIN document_types dt ON dt.id=d.type_id ORDER BY d.id DESC")->fetchAll();$types=$pdo->query("SELECT * FROM document_types")->fetchAll();$progs=$pdo->query("SELECT * FROM study_programs")->fetchAll();$stats=$pdo->query("SELECT COUNT(*) total,SUM(status='published') published,SUM(views) views,SUM(downloads) downloads FROM documents")->fetch();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard Admin</title><style>body{margin:0;font-family:Arial;background:#f4f7fb}.side{position:fixed;width:230px;height:100%;background:#073b8f;color:#fff;padding:25px}.main{margin-left:230px;padding:30px}.cards{display:flex;gap:15px;flex-wrap:wrap}.stat,.panel{background:#fff;padding:20px;border-radius:12px}.stat{min-width:150px}.panel{margin-top:20px}input,select,textarea{padding:10px;margin:4px;width:95%}button{padding:10px 16px}table{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}</style></head><body><aside class="side"><h2>REPOSITORY</h2><p>STIKes Namira Madina</p><p><?=e($_SESSION['user']['name'])?></p><a href="?logout=1" style="color:#fff">Keluar</a></aside><main class="main"><h1>Dashboard</h1><div class="cards"><div class="stat">Total<br><b><?=$stats['total']??0?></b></div><div class="stat">Published<br><b><?=$stats['published']??0?></b></div><div class="stat">Views<br><b><?=$stats['views']??0?></b></div><div class="stat">Downloads<br><b><?=$stats['downloads']??0?></b></div></div><section class="panel"><h2>Tambah Karya Ilmiah</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="save" value="1"><input name="title" placeholder="Judul" required><input name="author" placeholder="Penulis" required><input name="nim" placeholder="NIM"><select name="study_program_id"><option value="">Program Studi</option><?php foreach($progs as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select><select name="type_id"><option value="">Jenis Dokumen</option><?php foreach($types as $t):?><option value="<?=$t['id']?>"><?=e($t['name'])?></option><?php endforeach;?></select><input name="year" type="number" value="<?=date('Y')?>" required><textarea name="abstract" placeholder="Abstrak"></textarea><input name="keywords" placeholder="Kata kunci"><input type="file" name="pdf" accept="application/pdf"><select name="status"><option value="draft">Draft</option><option value="review">Review</option><option value="published">Published</option></select><button>Simpan</button></form></section><section class="panel"><h2>Kelola Koleksi</h2><table><tr><th>Judul</th><th>Penulis</th><th>Tahun</th><th>Status</th><th>Aksi</th></tr><?php foreach($docs as $d):?><tr><td><?=e($d['title'])?></td><td><?=e($d['author'])?></td><td><?=$d['year']?></td><td><?=$d['status']?></td><td><?php if($d['status']!=='published'):?><a href="?publish=<?=$d['id']?>">Publikasikan</a><?php else:?>Terbit<?php endif;?></td></tr><?php endforeach;?></table></section></main></body></html>